def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    # If opponent always cooperates, keep cooperating.
    if op_d == 0:
        return 'C'

    # If opponent always defects, defect (best response).
    if op_c == 0:
        return 'D'

    # Detect runs of opponent defections.
    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    # Punish persistent recent defection, but avoid endless retaliation loops
    # on the last round or when opponent has been mostly cooperative.
    if last == 'D':
        if run >= 2:
            return 'D'
        if op_d * 3 > n:
            return 'D'
        # Single occasional defection: retaliate lightly once, then return to C.
        if me and me[-1] == 'D':
            return 'C'
        return 'D'

    # Opponent just cooperated. Defect on the final round to exploit.
    if n == 100:
        return 'D'

    # If opponent's cooperation rate is high, mostly cooperate but occasionally
    # probe for exploitation near the end.
    if op_c * 5 >= n * 4:
        if n >= 95 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Mixed opponent: prefer cooperation unless recent behavior is poor.
    if op_d * 2 > n:
        return 'D'

    # Tit-for-tat with slight forgiveness: copy opponent's last move, but don't
    # get trapped in mutual defection after isolated noise.
    if me and op:
        if op[-1] == 'D' and len(op) >= 2 and op[-2] == 'C':
            return 'C'
        return op[-1]
    return 'C'
